- static bool are_sinks_equal(const struct dc_sink *sink1, const struct dc_sink *sink2)
- {
- 	if (!sink1 || !sink2)
- 		return false;
- 	if (sink1->sink_signal != sink2->sink_signal)
- 		return false;
