- 	if (aconnector &&
- 	    (aconnector->dc_link->connector_signal == SIGNAL_TYPE_HDMI_TYPE_A ||
- 	     aconnector->dc_link->connector_signal == SIGNAL_TYPE_HDMI_FRL ||
- 	     aconnector->dc_link->dpcd_caps.dongle_type == DISPLAY_DONGLE_DP_HDMI_CONVERTER))
