- static bool parse_edid_cea_dmub(struct amdgpu_display_manager *dm,
- 		u8 *edid_ext, int len,
- 		struct amdgpu_hdmi_vsdb_info *vsdb_info)
- {
- 	int i;
- 
- 	/* send extension block to DMCU for parsing */
- 	for (i = 0; i < len; i += 8) {
