- 	struct drm_connector *connector = &aconnector->base;
- 
- 	vsdb_info->replay_mode = connector->display_info.amd_vsdb.replay_mode;
- 	vsdb_info->amd_vsdb_version = connector->display_info.amd_vsdb.version;
